from collections import deque
class DataStream:
    def __init__(self, value: int, k: int):
        self.value = value
        self.k = k
        self.q = deque()
        self.matches = 0
    def consec(self, num: int) -> bool:
        self.q.append(num)
        if num == self.value:
            self.matches += 1
        if len(self.q) > self.k:
            old = self.q.popleft()
            if old == self.value:
                self.matches -= 1
        return len(self.q) == self.k and self.matches == self.k

