class DataStream {
    int value, k, matches = 0;
    deque<int> q;
public:
    DataStream(int value, int k) : value(value), k(k) {}
    bool consec(int num) {
        q.push_back(num);
        if (num == value) matches++;
        if ((int)q.size() > k) {
            if (q.front() == value) matches--;
            q.pop_front();
        }
        return (int)q.size() == k && matches == k;
    }
};

