var DataStream = function(value, k) {
    this.value = value;
    this.k = k;
    this.q = [];
    this.matches = 0;
};
DataStream.prototype.consec = function(num) {
    this.q.push(num);
    if (num === this.value) this.matches++;
    if (this.q.length > this.k) {
        if (this.q.shift() === this.value) this.matches--;
    }
    return this.q.length === this.k && this.matches === this.k;
};
